// MM.art: sprite atlas runtime for the art generated by tools/build-art.js (window.MM_ART).
// Classic script, file:// safe (images are data URIs). Every call is a safe no-op when the
// atlas or a sprite is missing, so callers can draw unconditionally and fall back to their own art.
//
//   MM.art.whenReady(cb) / await MM.art.whenReady()     fires once all sheets decoded (or none exist)
//   MM.art.draw(ctx, name, x, y, {frame, t, scale, flip, alpha, ax, ay, shadow}) -> true if drawn
//   MM.art.shadow(ctx, x, y, rx, ry)  crisp contact-shadow ellipse (sprites carry their size in .sh)
//   MM.art.get(name) -> {name, sheet, x, y, w, h, ax, ay, frames, fps, durs, loop, img} | null
//   MM.art.has(name), MM.art.names(prefix?), MM.art.frameAt(name, t), MM.art.tile(base, seed)
//   MM.art.drawTile(ctx, base, seed, x, y, opts)  (pick a ground variant and draw it)
window.MM = window.MM || {};
(function () {
  'use strict';
  const DATA = window.MM_ART || null;
  const art = {
    ready: false, version: DATA ? DATA.version : null, error: null,
    sheets: {}, index: {}, count: 0,
  };
  const waiting = [];
  const finish = () => {
    if (art.ready) return;
    art.ready = true;
    while (waiting.length) { const cb = waiting.shift(); try { cb(art); } catch (e) { console.error('MM.art.whenReady callback failed', e); } }
    try { window.MM.bus && window.MM.bus.emit && window.MM.bus.emit('art:ready', { count: art.count }); } catch (e) { /* bus optional */ }
  };

  // ---------------------------------------------------------------- loading
  if (DATA && DATA.sheets) {
    const names = Object.keys(DATA.sheets);
    let pending = names.length;
    const done = () => { if (--pending <= 0) finish(); };
    for (const sn of names) {
      const s = DATA.sheets[sn], img = new Image();
      art.sheets[sn] = { name: sn, img, w: s.w, h: s.h, loaded: false };
      for (const [n, f] of Object.entries(s.frames)) {
        art.index[n] = Object.assign({ name: n, sheet: sn, img }, f);
        if (f.durs) art.index[n].total = f.durs.reduce((a, b) => a + b, 0) / 1000;
        art.count++;
      }
      img.onload = () => { art.sheets[sn].loaded = true; done(); };
      img.onerror = () => { art.error = 'sheet ' + sn + ' failed to decode'; console.warn('MM.art: ' + art.error); done(); };
      img.src = s.src;
    }
    if (!names.length) finish();
  } else {
    art.error = 'window.MM_ART missing (assets/js/art-data.js not loaded)';
    finish();
  }

  // ---------------------------------------------------------------- queries
  art.whenReady = function (cb) {
    if (typeof cb === 'function') { if (art.ready) cb(art); else waiting.push(cb); return undefined; }
    return new Promise((res) => { if (art.ready) res(art); else waiting.push(res); });
  };
  art.get = (name) => art.index[name] || null;
  art.has = (name) => !!art.index[name];
  art.names = function (prefix) {
    const all = Object.keys(art.index);
    return (prefix ? all.filter((n) => n.startsWith(prefix)) : all).sort();
  };

  // Frame index for time t (seconds). Honors per-frame durations and loop:false (holds last frame).
  art.frameAt = function (name, t) {
    const f = art.index[name];
    if (!f || f.frames <= 1) return 0;
    t = Math.max(0, t || 0);
    if (f.durs) {
      let m = f.loop === false ? Math.min(t, f.total - 1e-6) : t % f.total;
      for (let i = 0; i < f.durs.length; i++) { m -= f.durs[i] / 1000; if (m < 0) return i; }
      return f.frames - 1;
    }
    const k = Math.floor(t * (f.fps || 8));
    return f.loop === false ? Math.min(k, f.frames - 1) : k % f.frames;
  };

  // Ground variants: tile('grass_grove', seed) -> 'grass_grove_2'. Falls back to the base name.
  const variantCache = {};
  art.tile = function (base, seed) {
    let v = variantCache[base];
    if (!v) v = variantCache[base] = art.names(base + '_').filter((n) => /^\d+$/.test(n.slice(base.length + 1)));
    if (!v.length) return art.has(base) ? base : null;
    let h = Math.floor(Number(seed) || 0) | 0;
    h = Math.imul(h ^ (h >>> 15), 2246822507); h = Math.imul(h ^ (h >>> 13), 3266489909); h = (h ^ (h >>> 16)) >>> 0;
    return v[h % v.length];
  };

  // ---------------------------------------------------------------- drawing
  // (x, y) is where the sprite's anchor pixel lands (bottom-centre ground point for props,
  // diamond centre for tiles, top-left for icons). flip: true|'x' mirrors around the anchor.
  art.draw = function (ctx, name, x, y, o) {
    const f = art.index[name];
    if (!f || !ctx || !art.sheets[f.sheet] || !art.sheets[f.sheet].loaded) return false;
    o = o || {};
    let fi = o.frame != null ? o.frame : o.t != null ? art.frameAt(name, o.t) : 0;
    fi = ((fi | 0) % f.frames + f.frames) % f.frames;
    const s = o.scale || 1, ax = o.ax != null ? o.ax : f.ax, ay = o.ay != null ? o.ay : f.ay;
    const flip = o.flip === true || o.flip === 'x';
    const dx = Math.round(x - (flip ? f.w - 1 - ax : ax) * s), dy = Math.round(y - ay * s);
    const sx = f.x + fi * f.w;
    const a0 = ctx.globalAlpha;
    if (o.alpha != null) ctx.globalAlpha = a0 * o.alpha;
    if (f.sh && (o.shadow != null ? o.shadow : f.autoShadow)) art.shadow(ctx, x, y + s, f.sh[0] * s, f.sh[1] * s);
    if (flip) {
      ctx.save(); ctx.translate(dx + f.w * s, dy); ctx.scale(-1, 1);
      ctx.drawImage(f.img, sx, f.y, f.w, f.h, 0, 0, f.w * s, f.h * s);
      ctx.restore();
    } else ctx.drawImage(f.img, sx, f.y, f.w, f.h, dx, dy, f.w * s, f.h * s);
    ctx.globalAlpha = a0;
    return true;
  };
  // Crisp pixel ellipse contact shadow (ink-teal, translucent), centred on (x, y).
  art.shadowColor = 'rgba(38,58,55,.22)';
  art.shadow = function (ctx, x, y, rx, ry) {
    if (!ctx || rx <= 0 || ry <= 0) return;
    ctx.fillStyle = art.shadowColor;
    for (let dy = -ry; dy <= ry; dy++) {
      const w = Math.round(rx * Math.sqrt(1 - (dy / (ry + 0.5)) ** 2));
      if (w > 0) ctx.fillRect(Math.round(x - w), Math.round(y + dy), w * 2, 1);
    }
  };
  art.drawTile = function (ctx, base, seed, x, y, o) {
    const n = art.tile(base, seed);
    return n ? art.draw(ctx, n, x, y, o) : false;
  };

  window.MM.art = art;
})();
